  "partTitleEn": "More Classes & Sentence Structure",
  "title": "Viashiria",
  "subtitle": "The Demonstratives",
  "note": "Swahili doesn't separate demonstrative adjectives from pronouns — \"this\" and \"this one\" are the same word. Proximity forms start with h- (huyu, hii...), distance forms end in -le (yule, ile...), and a third \"reference\" set points back to something already mentioned.",
