  "title": "Kitenzi KUWA",
  "subtitle": "The Verb KUWA = to Be",
  "note": "Kuwa (\"to be\") is unusually irregular: the modern present tense is just ni (affirmative) / si (negative) for every person, while other tenses use the roots -wa- or -li- depending on whether the meaning is descriptive or locative.",
