  "title": "Maneno ya Kuuliza",
  "subtitle": "Interrogative Words",
  "note": "Swahili doesn't invert word order to ask a question — intonation plus a question word does the job: nani? (who), nini? (what), lini? (when), wapi? (where), kwa nini? (why), namna gani?/vipi? (how).",
